// --- Global Variables for Uncler M Variants ---
var uM_colors = ["#1aff00", "#00ffff", "#ffff00", "#ff00ff", "#18181b"];
var speedMult = 2.5;
var lineScale = 1.3;
var dynamicShift = 0;
var scalePulse = 1.0;
var rotAngle = 0;
var gridOffset = 0;
var uM_rot = 0;

// === Inspired by 'FibonacciCurl' by 'Ivan Rudnicki' ===
// Created as variant #1 by Uncler M
// Infused with creative algorithmic modifications.

// === Tab: mySketch ===
// For #genuary2026, day 03: "fibonacci forever".

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	background(10, 10, 15);
	types = [OPEN, CHORD, PIE];
	dim = -PI;
	tindex = 2;
	sequence = generateFibonacci(15);
	lastdim = dim;
}

function draw() {
  // === Variant 1: Neon Kinetic Glitch Modification ===
  dynamicShift = sin((frameCount * speedMult) * 0.08) * 40;

	dim = 2 * TAU * sin((frameCount * speedMult) / 300);
	lastdim = dim;
	rotateZ(dim / 2)
	rotateY(dim / 2);
	rotateX(dim / 2);
	drawCurl();
}

function drawCurl() {
	for (let i = 0; i < sequence.length; i++) {
		let r = sequence[i] * dim;
		noFill();
		stroke(255, 50);
		strokeWeight(1.5);
		if (i > 2) translate(-(sequence[i - 1] * abs(dim)) / 2 + (sequence[i - 3] * abs(dim)) / 2, 0);
		arc(0, 0, r, r, 0, HALF_PI, types[tindex]);
		rotate(HALF_PI);
	}
}

function mousePressed() {
	fullscreen(true);
	tindex = (tindex + 1) % types.length;
	background(10, 10, 15);
}

function generateFibonacci(n) {
	let fib = [0, 1];
	for (let i = 2; i < n; i++) {
		fib.push(fib[i - 1] + fib[i - 2]);
	}
	return fib;
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}
